  "implementation": "def solve(case):
    segments = case.get('segments')
    budget = case.get('budget')
    if not isinstance(segments, list) or len(segments) == 0:
        raise ValueError('Invalid or missing segments')
    if not isinstance(budget, int) or budget < 0:
        raise ValueError('Budget must be a non-negative integer')
    names = []
    importances = []
    minima = []
    capacities = []
    for s in segments:
        name = s.get('name')
        imp = s.get('importance')
        mn = s.get('minimum')
        cap = s.get('capacity')
        if not isinstance(name, str) or not isinstance(imp, (int, float)) or not isinstance(mn, int) or not isinstance(cap, int):
            raise ValueError('Invalid segment field')
        if imp <= 0 or mn < 0 or cap < 0 or mn > cap:
            raise ValueError('Invalid segment constraints')
        names.append(name)
        importances.append(imp)
        minima.append(mn)
        capacities.append(cap)
    sum_min = sum(minima)
    sum_cap = sum(capacities)
    if budget < sum_min or budget > sum_cap:
        raise ValueError('Budget out of feasible range')
    alloc = list(minima)
    remaining = budget - sum_min
    while remaining > 0:
        best_idx = None
        best_ratio = -1.0
        for i, (imp, cur, cap) in enumerate(zip(importances, alloc, capacities)):
            if cur >= cap:
                continue
            ratio = imp / (cur + 1)
            if ratio > best_ratio:
                best_ratio = ratio
                best_idx = i
        if best_idx is None:
            break
        alloc[best_idx] += 1
        remaining -= 1
    allocations = {names[i]: alloc[i] for i in range(len(names))}
    total_allocated = sum(alloc)
    return {
        'allocations': allocations,
        'names': names,
        'total_allocated': total_allocated
    }"
}
